// Precompute modular inverse of 2 modulo n if possible
function egcd($a, $b) {
    if ($b == 0) return [$a, 1, 0];
    list($g, $x1, $y1) = egcd($b, $a % $b);
    return [$g, $y1, $x1 - intdiv($a, $b) * $y1];
