function gcd($a, $b) {
    $a = abs($a); $b = abs($b);
    while ($b != 0) {
        $t = $a % $b;
        $a = $b;
        $b = $t;
    }
    return $a;
}

// Compute S = sum_{i=0}^{t-1} (sx + sy + 2i + 2)
function computeS($sx, $sy, $t) {
    // S = t*(sx+sy+2) + 2 * t*(t-1)/2 = t*(sx+sy+2) + t*(t-1)
    $t1 = $t;
    $base = $sx + $sy + 2;
    $S = $t1 * $base + $t1 * ($t1 - 1);
    return $S;
}

$S = computeS($sx, $sy, $t);

// dx_t = dx + S, dy_t = dy + S
$dx_t = $dx + $S;
$dy_t = $dy + $S;

