// x_t = sx + t*dx + (S - t*(sx+sy+2))/2 mod n
// However, since n can be even, division by 2 modulo n is not always valid.
// We will use big integer arithmetic and then mod n.

$t_mod_n = $t % $n;

// Using 64-bit arithmetic carefully
$term = $t_mod_n * $dx;
$term2 = $t_mod_n * $dy;

