// y_t = sy + t*dy + (S - t*(sx+sy+2))/2

$base = $sx + $sy + 2;
$numerator = $S - $t * $base; // even integer
$half = intdiv($numerator, 2);

$x = $sx + $t * $dx + $half;
$y = $sy + $t * $dy + $half;

// Apply modulo n with proper positive result
$x = (($x - 1) % $n + $n) % $n + 1;
$y = (($y - 1) % $n + $n) % $n + 1;

echo $x . " " . $y . PHP_EOL;
